package com.nobi.appbuilder.events;

import com.nobi.appbuilder.model.EventModel;

/**
 * All triggers the workflow engine knows. Only click, long click and
 * text changed are generated by the Phase 7 code generator; the rest
 * are workflow/preview triggers and are reported as such, never
 * silently generated.
 */
public final class EventTrigger {

    public static final String CLICK = EventModel.EVENT_CLICK;
    public static final String LONG_CLICK = EventModel.EVENT_LONG_CLICK;
    public static final String TEXT_CHANGED = EventModel.EVENT_TEXT_CHANGED;
    public static final String SWITCH_CHANGED = "switch_changed";
    public static final String CHECKBOX_CHANGED = "checkbox_changed";
    public static final String IMAGE_CLICK = "image_click";
    public static final String TEXT_CLICK = "text_click";
    public static final String SCREEN_CREATED = "screen_created";
    public static final String SCREEN_RESUMED = "screen_resumed";
    public static final String FORM_SUBMITTED = "form_submitted";

    public static final String[] ALL = {
            CLICK, LONG_CLICK, TEXT_CHANGED, SWITCH_CHANGED, CHECKBOX_CHANGED,
            IMAGE_CLICK, TEXT_CLICK, SCREEN_CREATED, SCREEN_RESUMED,
            FORM_SUBMITTED
    };

    public static final String[] COMPONENT_TRIGGERS = {
            CLICK, LONG_CLICK, TEXT_CHANGED, SWITCH_CHANGED, CHECKBOX_CHANGED,
            IMAGE_CLICK, TEXT_CLICK, FORM_SUBMITTED
    };

    public static final String[] SCREEN_TRIGGERS = {
            SCREEN_CREATED, SCREEN_RESUMED
    };

    private EventTrigger() {
    }

    /** True when the Phase 7 generator can emit a listener for it. */
    public static boolean isCodegenSupported(String trigger) {
        return CLICK.equals(trigger) || LONG_CLICK.equals(trigger)
                || TEXT_CHANGED.equals(trigger);
    }

    public static boolean isScreenTrigger(String trigger) {
        return SCREEN_CREATED.equals(trigger)
                || SCREEN_RESUMED.equals(trigger);
    }

    public static boolean isKnown(String trigger) {
        if (trigger == null) {
            return false;
        }
        for (String known : ALL) {
            if (known.equals(trigger)) {
                return true;
            }
        }
        return false;
    }

    public static String displayName(String trigger) {
        if (trigger == null) {
            return "None";
        }
        switch (trigger) {
            case CLICK:
                return "On click";
            case LONG_CLICK:
                return "On long click";
            case TEXT_CHANGED:
                return "On text changed";
            case SWITCH_CHANGED:
                return "On switch changed";
            case CHECKBOX_CHANGED:
                return "On checkbox changed";
            case IMAGE_CLICK:
                return "On image click";
            case TEXT_CLICK:
                return "On text click";
            case SCREEN_CREATED:
                return "On screen created";
            case SCREEN_RESUMED:
                return "On screen resumed";
            case FORM_SUBMITTED:
                return "On form submitted";
            default:
                return trigger;
        }
    }
}
